// Extraer parámetros de query string
const query = $json.query || {};
const binaryData = $input.first().binary || {};
const binaryKeys = Object.keys(binaryData);

// IDs vienen en query parameters (inyectados por el backend desde sesión)
const required = ['curso_id', 'institucion_id'];
for (const key of required) {
  if (!query[key]) {
    throw new Error(`Falta el parámetro query requerido: ${key}`);
  }
}

if (binaryKeys.length === 0) {
  throw new Error('No se recibieron archivos PDF. Se esperan archivos en el campo "files".');
}

// Preparar lista de archivos para procesamiento
const archivos = binaryKeys.map(key => ({
  nombre: binaryData[key].fileName || key,
  datos: binaryData[key].data,
  tipo: binaryData[key].mimeType || 'application/pdf'
}));

// Normalizar y pasar datos al siguiente nodo
return [{
  json: {
    curso_id: String(query.curso_id),
    institucion_id: String(query.institucion_id),
    coordinador_id: String(query.coordinador_id || ''),
    namespace: `curso_${query.curso_id}`,
    archivos
  }
}];

const pdfParse = require('pdf-parse');

const ctx = $('Validar Entrada').item.json;
const archivos = ctx.archivos || [];

// Chunks pequeños (~320 palabras, ~40 de solape) mejoran la precisión de
// recuperación en RAG frente a chunks grandes; se recortan por página para
// que la cita (archivo + página) que se muestra al alumno sea siempre exacta.
const CHUNK_WORDS = 320;
const OVERLAP_WORDS = 40;

function sanitize(name) {
  return name.replace(/\.pdf$/i, '').replace(/[^a-zA-Z0-9_-]/g, '_');
}

function chunkWords(words, size, overlap) {
  const chunks = [];
  let i = 0;
  while (i < words.length) {
    const slice = words.slice(i, i + size);
    if (slice.join(' ').trim().length > 20) chunks.push(slice.join(' '));
    if (i + size >= words.length) break;
    i += (size - overlap);
  }
  return chunks;
}

const results = [];

// Procesar cada PDF recibido
for (const archivo of archivos) {
  try {
    // Decodificar PDF desde base64
    const pdfBuffer = Buffer.from(archivo.datos, 'base64');

    // pdf-parse invoca 'pagerender' una vez por página en orden; acumulamos el
    // texto de cada página para poder chunkear sin perder el número de página.
    const pages = [];
    const options = {
      pagerender: (pageData) => {
        return pageData.getTextContent({ normalizeWhitespace: true }).then((textContent) => {
          const text = textContent.items.map((item) => item.str).join(' ');
          pages.push(text);
          return text;
        });
      }
    };

    await pdfParse(pdfBuffer, options);

    const sanitizedName = sanitize(archivo.nombre);

    pages.forEach((pageText, pageIdx) => {
      const pageNumber = pageIdx + 1;
      const words = pageText.split(/\s+/).filter(Boolean);
      if (!words.length) return;

      const pageChunks = chunkWords(words, CHUNK_WORDS, OVERLAP_WORDS);
      pageChunks.forEach((texto, chunkIdx) => {
        results.push({
          json: {
            curso_id: ctx.curso_id,
            institucion_id: ctx.institucion_id,
            namespace: ctx.namespace,
            archivo: archivo.nombre,
            pagina: pageNumber,
            chunk_index: chunkIdx,
            texto,
            // ID determinístico: identificador único por curso/archivo/página/chunk
            vectorId: `curso_${ctx.curso_id}__${sanitizedName}__p${pageNumber}__c${chunkIdx}`
          }
        });
      });
    });
  } catch (e) {
    // PDF corrupto, protegido o sin texto: se omite
    continue;
  }
}

if (results.length === 0) {
  throw new Error('No se encontró texto extraíble en los PDFs proporcionados (¿están escaneados como imagen o protegidos?)');
}

return results;

const items = $input.all();
const textos = items.map((it) => it.json.texto);
const chunksMeta = items.map((it) => it.json);

return [{
  json: {
    textos,
    chunksMeta
  }
}];

const prep = $('Agrupar Textos para Embeddings').item.json;
const chunksMeta = prep.chunksMeta;
const embeddingsResp = $json;
const data = Array.isArray(embeddingsResp.data) ? embeddingsResp.data : [];

const vectors = chunksMeta.map((meta, idx) => {
  const embeddingItem = data.find((d) => d.index === idx) || data[idx];
  return {
    id: meta.vectorId,
    values: embeddingItem ? embeddingItem.embedding : [],
    metadata: {
      institucion_id: meta.institucion_id,
      curso_id: Number(meta.curso_id),
      archivo: meta.archivo,
      pagina: meta.pagina,
      chunk_index: meta.chunk_index,
      texto: meta.texto,
      indexed_at: new Date().toISOString()
    }
  };
}).filter((v) => v.values && v.values.length);

if (!vectors.length) {
  throw new Error('No se generaron embeddings válidos para los fragmentos extraídos');
}

return [{
  json: {
    namespace: chunksMeta[0].namespace,
    vectors
  }
}];

const ctx = $('Validar Entrada').item.json;
const chunkItems = $('Extraer PDFs por Pagina + Chunking').all();

const archivos = [...new Set(chunkItems.map((it) => it.json.archivo))];
const paginas = new Set(chunkItems.map((it) => `${it.json.archivo}::${it.json.pagina}`)).size;

return [{
  json: {
    success: true,
    curso_id: Number(ctx.curso_id),
    namespace: ctx.namespace,
    archivos_procesados: archivos.length,
    paginas_procesadas: paginas,
    chunks_indexados: chunkItems.length,
    indexed_at: new Date().toISOString()
  }
}];
